package com.zerotrust.internalresource.entity;
import jakarta.persistence.*;import java.time.Instant;
@Entity @Table(name="file_resources") public class FileResourceEntity{@Id @GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@Column(nullable=false,updatable=false)private String resourceId;@Column(nullable=false)private String name;@Column(nullable=false)private String description;@Column(nullable=false)private String category;@Column(nullable=false)private String owner;@Column(nullable=false)private String department;@Column(nullable=false)private String classificationLevel;@Column(nullable=false)private String status;@Column(nullable=false)private Instant createdAt;@Column(nullable=false)private Instant updatedAt;public FileResourceEntity(){}public Long getId(){return id;}public String getResourceId(){return resourceId;}public void setResourceId(String v){resourceId=v;}public String getName(){return name;}public void setName(String v){name=v;}public String getDescription(){return description;}public void setDescription(String v){description=v;}public String getCategory(){return category;}public void setCategory(String v){category=v;}public String getOwner(){return owner;}public void setOwner(String v){owner=v;}public String getDepartment(){return department;}public void setDepartment(String v){department=v;}public String getClassificationLevel(){return classificationLevel;}public void setClassificationLevel(String v){classificationLevel=v;}public String getStatus(){return status;}public void setStatus(String v){status=v;}public Instant getCreatedAt(){return createdAt;}public void setCreatedAt(Instant v){createdAt=v;}public Instant getUpdatedAt(){return updatedAt;}public void setUpdatedAt(Instant v){updatedAt=v;}}
